import path from "path";
import { type FileNode } from "./fs-inspector.js";

// A simple dictionary mapping file extensions to readable language names
const EXTENSION_MAP: Record<string, string> = {
    ".ts": "TypeScript",
    ".js": "JavaScript",
    ".json": "JSON",
    ".md": "Markdown",
    ".py": "Python",
    ".html": "HTML",
    ".css": "CSS",
    ".pdf": "PDF"
};

/**
 * Walks through a file tree and counts the programming languages used.
 * @param nodes The file tree structure generated by fs-inspector
 * @returns An object containing the language names and their counts
 */
export function analyzeLanguages(nodes: FileNode[]): Record<string, number> {
    const languageCounts: Record<string, number> = {};

    // We define a helper function inside so it has access to the languageCounts object
    function traverse(currentNodes: FileNode[]) {
        for (const node of currentNodes) {
            if (node.type === "file") {
                // Get the extension (e.g., ".ts") using the path module
                const ext = path.extname(node.name).toLowerCase();

                // Look up the language, or default to "Unknown" if it's not in our map
                const language = EXTENSION_MAP[ext] || "Unknown";

                // Increment the counter for this language
                if (languageCounts[language]) {
                    languageCounts[language]++;
                } else {
                    languageCounts[language] = 1;
                }
            } else if (node.type === "directory" && node.children) {
                // RECURSION: If it's a directory, walk through its children
                traverse(node.children);
            }
        }
    }

    // Start the traversal with the initial nodes
    traverse(nodes);

    return languageCounts;
}
